<script setup lang="ts">
import { computed, nextTick, useTemplateRef, watch } from 'vue'
import { ArrowLeft, ArrowRight, Check, Loader2, LogOut, Sparkles } from 'lucide-vue-next'
import { useAuth } from '@/composables/useAuth'
import { useOnboarding } from '@/composables/useOnboarding'
import ProfileStep from '@/components/onboarding/ProfileStep.vue'
import MetricsStep from '@/components/onboarding/MetricsStep.vue'
import GoalStep from '@/components/onboarding/GoalStep.vue'
import ReviewStep from '@/components/onboarding/ReviewStep.vue'

const { logout } = useAuth()
const { form, step, steps, errors, submitting, locked, uncertain, error, currentGoal, next, back, submit } = useOnboarding()
const heading = useTemplateRef<HTMLHeadingElement>('heading')
const titles = ['Mọi hành trình bắt đầu\ntừ chính bạn.', 'Lắng nghe\ncơ thể mình.', 'Chọn một hướng đi.\nVững bước mỗi ngày.', 'Lời hẹn đầu tiên\nvới chính mình.']
const descriptions = ['Một vài thông tin để HercFit hiểu nhịp sống và đồng hành cùng bạn.', 'Ghi lại điểm xuất phát để nhìn thấy những thay đổi trên hành trình.', 'Mục tiêu do bạn chọn. HercFit giúp bạn ghi nhận từng bước tiến.', 'Xem lại những gì bạn đã chia sẻ trước khi bắt đầu.']
const title = computed(() => titles[step.value])
function advance() { if (step.value === 3) submit(); else next() }
watch(step, async () => { await nextTick(); heading.value?.focus({preventScroll:true}); heading.value?.scrollIntoView({block:'nearest'}) })
</script>

<template>
  <main class="onboarding-page">
    <div aria-hidden="true" class="grain-overlay pointer-events-none" />
    <header class="onboarding-header"><a href="/" class="onboarding-brand">MYTHIC <span>// OLYMPUS KINETIC</span></a><button type="button" class="exit-button" :disabled="submitting" @click="logout"><LogOut :size="13" /><span>Đăng xuất</span></button></header>
    <div class="onboarding-layout">
      <aside class="origin-story">
        <div class="story-copy"><p class="eyeline"><Sparkles :size="12" /> YOUR PERSONAL ODYSSEY</p><h1>Khởi đầu<br />một hành trình<br /><em>của riêng bạn.</em></h1><p>Không cần trở thành một vị thần.<br />Chỉ cần tốt hơn chính mình, từng ngày.</p></div>
        <div aria-hidden="true" class="origin-art"><div class="orbit orbit-outer" /><div class="orbit orbit-inner" /><img src="/images/hero-sculpture.png" alt="" /><span class="art-star star-one">✦</span><span class="art-star star-two">✧</span><span class="art-caption">THE BEGINNING OF YOUR ASCENT</span></div>
        <div class="story-footer"><span>HERC FIT / PERSONAL ARCHIVE</span><span>EST. OLYMPUS</span></div>
      </aside>
      <section class="onboarding-workspace" aria-label="Thiết lập hồ sơ cá nhân">
        <nav class="step-navigation" aria-label="Các bước thiết lập"><ol><li v-for="(label,index) in steps" :key="label" :class="{current:index===step,complete:index<step}" :aria-current="index===step ? 'step' : undefined"><span class="step-number"><Check v-if="index<step" :size="12" /><template v-else>{{ String(index+1).padStart(2,'0') }}</template></span><span>{{ label }}</span></li></ol></nav>
        <div class="onboarding-form-area"><p class="eyeline">THIẾT LẬP HỒ SƠ · {{ String(step+1).padStart(2,'0') }} / 04</p><h2 ref="heading" tabindex="-1" class="step-heading">{{ title }}</h2><p class="step-description">{{ descriptions[step] }}</p>
          <form class="onboarding-form" novalidate @submit.prevent="advance">
            <fieldset :disabled="locked">
              <ProfileStep v-if="step===0" v-model="form" :errors="errors" />
              <MetricsStep v-else-if="step===1" v-model="form" :errors="errors" />
              <GoalStep v-else-if="step===2" v-model="form" :errors="errors" :existing-goal="currentGoal?.title" />
              <ReviewStep v-else v-model="form" :errors="errors" :existing-goal="currentGoal?.title" />
            </fieldset>
            <div v-if="error" class="submit-error" role="alert">{{ error }}</div>
            <div class="form-actions"><button v-if="step>0" type="button" class="back-button" :disabled="locked" @click="back"><ArrowLeft :size="15" />Quay lại</button><span v-else class="required-note">* Thông tin bắt buộc</span><button type="submit" class="continue-button" :disabled="submitting"><Loader2 v-if="submitting" :size="16" class="saving-spinner" /><template v-else>{{ step===3 ? uncertain ? 'Thử lưu lại' : 'Bắt đầu hành trình' : 'Tiếp tục' }}<ArrowRight :size="16" /></template><span v-if="submitting">Đang lưu hồ sơ…</span></button></div>
          </form>
          <p class="form-footnote">Hồ sơ chỉ được lưu khi bạn xác nhận ở bước cuối.</p>
        </div>
      </section>
    </div>
  </main>
</template>

